create function public.create_manager_profile(p_name text,p_description text,p_acknowledged boolean,p_reason text,p_demo boolean default true,p_consent boolean default false)returns uuid language plpgsql security definer set search_path='' as $$declare mid uuid;begin perform private.require_administrator();perform private.catalogue_lock();perform private.check_record_mode(p_demo,p_consent);mid:=private.create_manager_original(p_name,p_description,p_acknowledged,p_reason);update public.landlords set is_demo=p_demo where id=mid;return mid;end;$$;
