alter function public.merge_properties(uuid,uuid,uuid[],uuid[],text,text,text)set schema private;alter function private.merge_properties(uuid,uuid,uuid[],uuid[],text,text,text)rename to merge_before_record_mode;revoke all on function private.merge_before_record_mode(uuid,uuid,uuid[],uuid[],text,text,text)from public,anon,authenticated,service_role;
create function public.merge_properties(p_source uuid,p_target uuid,p_archive uuid[],p_revoke uuid[],p_history text,p_details text,p_reason text)returns void language plpgsql security definer set search_path='' as $$begin perform private.require_administrator();perform private.catalogue_lock();if(select is_demo from public.properties where id=p_source)is distinct from(select is_demo from public.properties where id=p_target)then raise exception 'Cannot merge demonstration and real profiles';end if;perform private.merge_before_record_mode(p_source,p_target,p_archive,p_revoke,p_history,p_details,p_reason);end;$$;
