alter table private.review_photos add column cleanup_queued_at timestamptz;
alter table private.property_photos add column cleanup_queued_at timestamptz;
create function public.queue_retired_photos(p_limit integer default 100)returns integer language plpgsql security definer set search_path='' as $$
declare total integer:=0;amount integer;begin perform private.catalogue_lock();
with retired as(select ph.id from private.review_photos ph join public.reviews r on r.id=ph.review_id where ph.cleanup_queued_at is null and(ph.status in('deleted','removed')or r.status='deleted')order by ph.id limit least(greatest(coalesce(p_limit,100),1),1000)),queued as(insert into private.media_purge_queue(user_id,bucket,object_path)select t.user_id,'review-photos',ph.object_path from private.review_photos ph join retired e on e.id=ph.id join public.reviews r on r.id=ph.review_id join private.tenancies t on t.id=r.tenancy_id on conflict(bucket,object_path)do nothing),marked as(update private.review_photos set cleanup_queued_at=now()where id in(select id from retired)returning id)select count(*)into amount from marked;total:=total+amount;
with retired as(select id from private.property_photos where cleanup_queued_at is null and status in('deleted','removed')order by id limit least(greatest(coalesce(p_limit,100),1),1000)),queued as(insert into private.media_purge_queue(user_id,bucket,object_path)select owner_id,'review-photos',object_path from private.property_photos ph join retired e on e.id=ph.id on conflict(bucket,object_path)do nothing),marked as(update private.property_photos set cleanup_queued_at=now()where id in(select id from retired)returning id)select count(*)into amount from marked;return total+amount;end;$$;
revoke all on function public.queue_retired_photos(integer)from public,anon,authenticated;grant execute on function public.queue_retired_photos(integer)to service_role;
